# Reverse dependency order. Populated reference/history/job records must be exported first.
TABLES = (
    "workforce_observations",
    "occupational_tasks",
    "occupation_skills",
    "ai_impact_evidence",
    "skills",
    "sdg_references",
    "occupations",
    "evidence_processing_logs",
    "academic_standards",
    "evidence_references",
    "evidence_ingestion_jobs",
    "dataset_versions",
    "datasets",
)


def downgrade() -> None:
    query = "SELECT " + " + ".join(f"(SELECT count(*) FROM {name})" for name in TABLES)
    message = "Export Phase 3 reference evidence before downgrade; refusing data loss"
    if context.is_offline_mode():
        op.execute(
            "DO $$ BEGIN IF ("
            + query
            + ") > 0 THEN RAISE EXCEPTION '"
            + message
            + "'; END IF; END $$"
        )
    elif op.get_bind().scalar(sa.text(query)):
        raise RuntimeError(message)
    for name in TABLES:
        op.drop_table(name)
